CREATE TABLE IF NOT EXISTS bak_20261105_bp26_ib_cards AS SELECT * FROM human_actions WHERE slug IN ('bp26-social-bot-labels', 'bp26-email-agent-ai-disclosure');

UPDATE human_actions
SET status = 'open', resolved_at = NULL, resolution = NULL, updated_at = datetime('now'),
    why = why || ' REOPENED 2026-11-05 (BP26-IB-CARDS-1): the card was closed at birth on its default while metric social_bot_label_enabled (trigger 14495, issue 1000519) sits at 0 with no step the fleet may take. Measured live: Bluesky qnfo.org (labels none) and Mastodon @QNFO@mstdn.science (bot flag off) are both in your name, so the fleet will not write a platform label on them by itself. The default stays in effect (in-text marker on every post). Closing probe: metric 14495 reads 1, or your answer ''not on personal accounts'', after which the fleet rescopes the metric to the in-text marker and records it in decision_log.'
WHERE slug = 'bp26-social-bot-labels' AND status = 'resolved' AND resolution LIKE 'DEFAULT-ADOPTED-1%';

UPDATE human_actions
SET status = 'open', resolved_at = NULL, resolution = NULL, updated_at = datetime('now'),
    why = why || ' REOPENED 2026-11-05 (BP26-IB-CARDS-1): the card was closed at birth on its default while metric ai_interaction_disclosure (trigger 14498, issue 1000521) reads 0.6667: ipatent and the twin disclose on their first screen, the e-mail agent does not. A code task that would put a notice into replies sent in your name was parked and is not built. The default stays in effect (no change). Closing probe: metric 14498 reads 1 after your answer ''disclose'' (the fleet then adds the notice), or your answer ''keep'', after which the fleet rescopes the metric to the surfaces that speak as the fleet and records it in decision_log.'
WHERE slug = 'bp26-email-agent-ai-disclosure' AND status = 'resolved' AND resolution LIKE 'DEFAULT-ADOPTED-1%';

UPDATE agent_issues
SET description = description || char(10) || 'DELTA-NOTE (breach-bp26-reach, 2026-11-05): producer checked, valid. Bluesky qnfo.org labels none, Mastodon @QNFO bot=false, X and LinkedIn unverifiable: 0 of 4. Both readable profiles are in the owner''s name, so the platform label is the owner''s setting (IDENTITY-BOUND card bp26-social-bot-labels, reopened by migrations/2026-11-05-bp26-ib-cards-and-latency-notes.sql with its default in effect). The lever-review proposal to write a Bluesky bot self-label from qnfo-social syncProfile is not built for that reason. Note for whoever rescopes after the answer: 1.0 needs X and LinkedIn too; X cannot be read without credentials and LinkedIn offers no automated-account label, so the target as written is unreachable even after the owner acts. Blocker: owner answer. Closing probe: this issue''s contract (metric 14495).',
